function init3d(){scene=new THREE.Scene();scene.background=new THREE.Color(0x090b10);scene.fog=new THREE.Fog(0x090b10,55,230);camera=new THREE.PerspectiveCamera(78,innerWidth/innerHeight,.1,1200);scene.add(camera);renderer=new THREE.WebGLRenderer({canvas:$("game"),antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x090b10,1);clock=new THREE.Clock();scene.add(new THREE.HemisphereLight(0xfff5df,0x101827,1.85));const l=new THREE.DirectionalLight(0xffe5bd,1.35);l.position.set(22,34,12);scene.add(l);const fill=new THREE.PointLight(0x48cfff,.85,190);fill.position.set(0,18,0);scene.add(fill);floor=new THREE.Mesh(new THREE.PlaneGeometry(arenaRadius*2.28,arenaRadius*2.28,56,56),new THREE.MeshStandardMaterial({color:0x3f444a,roughness:.96,metalness:.02}));floor.rotation.x=-Math.PI/2;floor.position.y=-1.32;scene.add(floor);playerBody=new THREE.Object3D();scene.add(playerBody);addArena();addEvents();refreshSelfVisual();refreshViewModel()}
function addArena(){const sandMat=new THREE.MeshBasicMaterial({color:0x5c6167}),stoneMat=new THREE.MeshStandardMaterial({color:0x72777c,roughness:.92,metalness:.04}),darkStone=new THREE.MeshStandardMaterial({color:0x34383d,roughness:.88}),wallMat=new THREE.MeshStandardMaterial({color:0x777d83,roughness:.9,side:THREE.DoubleSide});const base=new THREE.Mesh(new THREE.CylinderGeometry(arenaRadius+8,arenaRadius+8,1.2,128),stoneMat);base.position.y=-1.55;scene.add(base);const sand=new THREE.Mesh(new THREE.CircleGeometry(arenaRadius,128),sandMat);sand.rotation.x=-Math.PI/2;sand.position.y=-.92;scene.add(sand);const wall=new THREE.Mesh(new THREE.CylinderGeometry(arenaRadius+2,arenaRadius+2,15,128,1,true),wallMat);wall.position.y=6.2;scene.add(wall);for(let i=0;i<5;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(arenaRadius+2+i*2.15,.55,10,160),i%2?darkStone:stoneMat);ring.rotation.x=Math.PI/2;ring.position.y=1.3+i*3.05;scene.add(ring)}for(let i=0;i<96;i++){const a=i/96*Math.PI*2,x=Math.cos(a)*(arenaRadius+2.8),z=Math.sin(a)*(arenaRadius+2.8),h=11.5+(i%4)*.65;const col=new THREE.Mesh(new THREE.CylinderGeometry(.58,.82,h,14),stoneMat);col.position.set(x,h/2-1,z);col.rotation.y=-a;scene.add(col);const cap=new THREE.Mesh(new THREE.BoxGeometry(2.1,.45,1.55),darkStone);cap.position.set(x,h-1,z);cap.rotation.y=-a;scene.add(cap)}}

function elementColor(id){return (elements[id]||elements.fire).color}
function mat(id,em=.25){const c=elementColor(id);return new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:em,roughness:.5,metalness:.08,transparent:false})}
function disposeObj(o){if(!o)return;o.traverse?.(x=>{if(x.geometry)x.geometry.dispose?.();if(x.material)x.material.dispose?.()});scene.remove(o)}
function makeCapsuleBody(radius,height,material){if(THREE.CapsuleGeometry)return new THREE.Mesh(new THREE.CapsuleGeometry(radius,height,8,16),material);const g=new THREE.Group(),cyl=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,height,16),material),top=new THREE.Mesh(new THREE.SphereGeometry(radius,16,10),material),bot=new THREE.Mesh(new THREE.SphereGeometry(radius,16,10),material);top.position.y=height/2;bot.position.y=-height/2;g.add(cyl,top,bot);return g}
function addElementDetails(root,id,color,self=false){const glow=new THREE.MeshBasicMaterial({color,transparent:true,opacity:self?.46:.74});if(id==="fire"){[-.32,0,.32].forEach((x,i)=>{const f=new THREE.Mesh(new THREE.ConeGeometry(.18,.72,12),glow);f.position.set(x,1.9+.12*i,0);f.rotation.z=x*.7;root.add(f)})}else if(id==="water"){for(let i=0;i<4;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(.18-i*.02,12,8),glow);const a=i*Math.PI*.5;b.position.set(Math.cos(a)*.88,.52+i*.18,Math.sin(a)*.88);root.add(b)}}else if(id==="lightning"){for(let i=0;i<4;i++){const bolt=new THREE.Mesh(new THREE.BoxGeometry(.08,.7,.08),glow);bolt.position.set((i-1.5)*.28,.85+(i%2)*.35,0);bolt.rotation.z=(i%2?.75:-.75);root.add(bolt)}}else if(id==="earth"){[-.55,.55].forEach(x=>{const s=new THREE.Mesh(new THREE.DodecahedronGeometry(.32,0),glow);s.position.set(x,.82,0);s.scale.y=.75;root.add(s)})}else if(id==="wind"){for(let i=0;i<3;i++){const r=new THREE.Mesh(new THREE.TorusGeometry(.88+i*.18,.025,8,54),glow);r.rotation.x=Math.PI/2;r.position.y=.15+i*.42;root.add(r)}}else if(id==="light"){const halo=new THREE.Mesh(new THREE.TorusGeometry(.55,.035,8,48),glow);halo.position.y=2.05;halo.rotation.x=Math.PI/2;root.add(halo)}else if(id==="darkness"){const hood=new THREE.Mesh(new THREE.TorusGeometry(.5,.08,8,32),glow);hood.position.y=1.55;hood.rotation.x=Math.PI/2;root.add(hood)}else if(id==="poison"){for(let i=0;i<6;i++){const a=i*Math.PI/3,spike=new THREE.Mesh(new THREE.ConeGeometry(.09,.48,8),glow);spike.position.set(Math.cos(a)*.72,.72,Math.sin(a)*.72);spike.rotation.z=Math.cos(a)*.8;spike.rotation.x=Math.sin(a)*.8;root.add(spike)}}else if(id==="dragon"){[-.55,.55].forEach(x=>{const wing=new THREE.Mesh(new THREE.ConeGeometry(.42,1.25,4),glow);wing.position.set(x,1.05,.18);wing.rotation.z=x>0?-.95:.95;root.add(wing)});const tail=new THREE.Mesh(new THREE.ConeGeometry(.16,.9,10),glow);tail.position.set(0,.22,.72);tail.rotation.x=Math.PI/2;root.add(tail)}else if(id==="psychic"){for(let i=0;i<3;i++){const hex=new THREE.Mesh(new THREE.TorusGeometry(.62+i*.18,.025,6,6),glow);hex.rotation.x=Math.PI/2;hex.rotation.z=i*.5;hex.position.y=.65+i*.32;root.add(hex)}}else if(id==="summoner"){["fire","water","wind","earth"].forEach((sid,i)=>{const c=elementColor(sid),orb=new THREE.Mesh(new THREE.SphereGeometry(.13,10,8),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.78}));const a=i*Math.PI/2;orb.position.set(Math.cos(a)*.9,.86,Math.sin(a)*.9);orb.userData.orbit={base:a,rad:.9,speed:1.35,h:.86};root.add(orb)})}else if(id==="hacker"){for(let i=0;i<5;i++){const bit=new THREE.Mesh(new THREE.BoxGeometry(.16,.08,.04),glow);bit.position.set((i-2)*.22,.55+(i%2)*.42,.58);bit.rotation.y=i*.6;root.add(bit)}}}
function makeAvatar(p,self=false){const root=new THREE.Group(),id=p.element||"fire",color=elementColor(id),bodyMat=mat(id,p.oluo?.92:p.devil?.65:.28);let body;if(id==="fire"){body=new THREE.Mesh(new THREE.ConeGeometry(.82,2.25,22),bodyMat);body.position.y=.08}else if(id==="water"){body=new THREE.Mesh(new THREE.SphereGeometry(.88,24,16),bodyMat);body.scale.y=1.5}else if(id==="lightning"){body=new THREE.Mesh(new THREE.OctahedronGeometry(1.02,1),bodyMat);body.scale.y=1.65}else if(id==="earth"){body=new THREE.Mesh(new THREE.DodecahedronGeometry(1.02,0),bodyMat);body.scale.y=1.42}else if(id==="wind"){body=new THREE.Mesh(new THREE.TorusKnotGeometry(.54,.19,72,10),bodyMat);body.scale.set(1.3,1.82,1.3)}else if(id==="light"){body=new THREE.Mesh(new THREE.IcosahedronGeometry(.95,1),bodyMat);body.scale.y=1.5}else if(id==="darkness"){body=makeCapsuleBody(.58,1.48,bodyMat);body.scale.y=1.16}else if(id==="dragon"){body=new THREE.Mesh(new THREE.ConeGeometry(.9,2.35,5),bodyMat);body.scale.y=p.dragonComplete?1.8:1.28}else if(id==="psychic"){body=new THREE.Mesh(new THREE.OctahedronGeometry(.92,1),bodyMat);body.scale.y=1.45}else if(id==="hacker"){body=new THREE.Mesh(new THREE.BoxGeometry(1.05,1.9,.72),bodyMat)}else{body=makeCapsuleBody(.54,1.35,bodyMat);body.scale.y=1.22}root.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,18,14),bodyMat);head.position.y=p.dragonComplete?2.35:1.55;root.add(head);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.06,.045,8,56),new THREE.MeshBasicMaterial({color,transparent:true,opacity:self?.46:.72}));ring.rotation.x=Math.PI/2;ring.position.y=-.82;root.add(ring);if(p.devil){const horns=new THREE.Group();[-.24,.24].forEach(x=>{const h=new THREE.Mesh(new THREE.ConeGeometry(.12,.45,8),new THREE.MeshBasicMaterial({color:0x210010}));h.position.set(x,1.92,0);horns.add(h)});root.add(horns)}if(p.evolve>=5){const aura=new THREE.Mesh(new THREE.TorusGeometry(1.32,.05,8,64),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.58}));aura.rotation.x=Math.PI/2;aura.position.y=.72;root.add(aura)}if(p.oluo){const crown=new THREE.Mesh(new THREE.TorusKnotGeometry(.44,.055,64,6),new THREE.MeshBasicMaterial({color:0xfff5b6,transparent:true,opacity:.9}));crown.position.y=2.14;root.add(crown)};(p.secondaryElements||[]).slice(0,3).forEach((sid,i)=>{const c=elementColor(sid),g=sid==="water"?new THREE.SphereGeometry(.14,10,8):sid==="fire"?new THREE.ConeGeometry(.12,.3,9):sid==="lightning"?new THREE.OctahedronGeometry(.16,0):sid==="earth"?new THREE.DodecahedronGeometry(.16,0):new THREE.SphereGeometry(.13,8,6);const o=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:self?.5:.86}));const a=i*Math.PI*2/3;o.position.set(Math.cos(a)*1.2,.68+i*.2,Math.sin(a)*1.2);o.userData.orbit={base:a,rad:1.2,speed:1.1+i*.35,h:.68+i*.2};root.add(o)});addElementDetails(root,id,color,self);root.userData.element=id;root.userData.secondary=(p.secondaryElements||[]).join(",");root.userData.devil=!!p.devil;root.userData.oluo=!!p.oluo;root.userData.evolve=p.evolve||0;root.userData.dragonComplete=!!p.dragonComplete;return root}
function refreshSelfVisual(){if(!scene)return;disposeObj(selfVisual);selfVisual=makeAvatar(local,true);selfVisual.scale.set(.36,.36,.36);scene.add(selfVisual)}
function refreshViewModel(){if(!camera)return;if(viewModel)camera.remove(viewModel);const id=local.element||"fire",color=elementColor(id),m=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.82}),g=new THREE.Group(),left=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),m),right=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),m),core=new THREE.Mesh(new THREE.TorusGeometry(.11,.012,8,28),m);left.position.set(-.32,-.22,-.72);right.position.set(.32,-.22,-.72);core.position.set(0,-.18,-.88);core.rotation.x=Math.PI/2;g.add(left,right,core);viewModel=g;camera.add(viewModel)}
function updateAvatar(root,dt){const t=performance.now()*.001;root.children.forEach(o=>{if(o.userData.orbit){const a=o.userData.orbit.base+t*o.userData.orbit.speed;o.position.x=Math.cos(a)*o.userData.orbit.rad;o.position.z=Math.sin(a)*o.userData.orbit.rad;o.position.y=o.userData.orbit.h+Math.sin(t*2+a)*.08}});root.rotation.y+=dt*.8}
function visualChanged(mesh,p){return mesh.userData.element!==(p.element||"fire")||mesh.userData.secondary!==(p.secondaryElements||[]).join(",")||mesh.userData.devil!==!!p.devil||mesh.userData.oluo!==!!p.oluo||mesh.userData.evolve!==(p.evolve||0)||mesh.userData.dragonComplete!==!!p.dragonComplete}




const BFCore=(()=>{
const elementIndex={fire:0,water:1,lightning:2,earth:3,wind:4,light:5,darkness:6,poison:7,dragon:8,psychic:9,summoner:10,hacker:11};
const cardTypeIndex=card=>card?.type==="CC기"||card?.stun||card?.slow||card?.pull?2:card?.type==="방어"||card?.shield||card?.heal?1:0;
const cardRange=radius=>radius*2+32;
const aimEndpoint=({pos,rot,origin:givenOrigin,floorY,arenaRadius,moveLimit})=>{
  const range=cardRange(arenaRadius),pitch=Math.max(-1.18,Math.min(1.18,rot?.x||0)),cp=Math.cos(pitch);
  const v={x:-Math.sin(rot?.y||0)*cp,y:Math.sin(pitch),z:-Math.cos(rot?.y||0)*cp},origin=givenOrigin||{x:pos.x,y:(pos.y||2)+.25,z:pos.z};
  let dist=range;
  if(v.y<-.025){const floorDist=(origin.y-floorY)/-v.y;if(floorDist>.01&&floorDist<range)dist=floorDist}
  const end={x:origin.x+v.x*dist,y:floorY,z:origin.z+v.z*dist},d=Math.hypot(origin.x+v.x*dist,origin.z+v.z*dist);
  if(d>moveLimit&&d>.001){end.x=end.x/d*moveLimit;end.z=end.z/d*moveLimit}
  end.distance=Math.hypot(end.x-origin.x,end.z-origin.z);
  return end;
};
const speed=(element,card)=>{
  const id=elementIndex[element]??0,type=cardTypeIndex(card),ult=card?.ultimate||card?.type==="궁극기";
  if(card?.psychicLift)return 6;
  if(card?.wave)return 3.8;
  if(card?.shield||card?.heal||card?.gravity||card?.roundSeal||card?.firePillar)return 0;
  if(card?.sun)return Math.max(3,Math.min(5,5-(card.charge||0)*2));
  if(card?.stream)return id===2||id===5||id===8?10:id===4||id===11?9:id===1||id===7||id===9?8:id===3?6:7;
  if(ult)return id===8?0:id===0?4:id===1?5:id===2?10:id===3?5:id===4?1:id===5?10:id===7||id===10?2:4;
  if(type===2)return id===8||id===0?0:id===2?10:id===3||id===7?5:id===5||id===9?9:id===11?8:6;
  return id===2||id===5?10:id===11||id===4?9:id===1||id===7||id===9?8:id===3?6:7;
};
const impactDelay=(element,card,dist=0)=>{
  const id=elementIndex[element]??0,s=speed(element,card),cc=cardTypeIndex(card)===2,ult=card?.ultimate||card?.type==="궁극기";
  if(card?.wave)return 1.05;
  if(card?.firePillar)return .82;
  if(s<=0)return cc?Math.max(.42,Math.min(1.35,(id===0 ? .55 : .42)+dist*.004)):.16;
  let wind=card?.stream ? .1 : .24;
  if(cc)wind+=id===2 ? .62 : id===5 ? .52 : id===0||id===3 ? .55 : .42;
  if(ult)wind+=id===4 ? .82 : id===2 ? .85 : id===3 ? .95 : id===5 ? .9 : id===7 ? .82 : .72;
  if(card?.sun)wind=.72+(card.charge||0)*.42;
  if(card?.psychicLift)wind+=.35;
  const world=card?.stream?18+s*4.8:9+s*3.6,low=card?.stream ? .18 : .34,high=card?.stream?1.35:2.75;
  return Math.max(low,Math.min(high,wind+dist/world));
};
const lineHit=args=>{
  const dx=args.targetX-args.originX,dz=args.targetZ-args.originZ,along=dx*args.dirX+dz*args.dirZ,lateral=Math.abs(dx*args.dirZ-dz*args.dirX),impact=Math.hypot(args.targetX-args.hitX,args.targetZ-args.hitZ),body=args.bodyRadius||0;
  return along>-body&&along<=args.range+body&&lateral<=args.radius+body||impact<=args.radius+body;
};
const upgradeDelayMs=readyCount=>readyCount>0?5000:0;
return{elementIndex,cardTypeIndex,cardRange,aimEndpoint,speed,impactDelay,lineHit,upgradeDelayMs};
})();
window.BFCore=BFCore;



function setSelectedCard(i){selectedCard=(i+4)%4;renderCards()}
function addEvents(){
  addEventListener("resize",()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
  addEventListener("keydown",e=>{
    if(e.target?.id==="chatInput"){if(e.code==="Escape"){e.preventDefault();closeChat()}return}
    if(e.code==="Escape"&&!$("hud").classList.contains("hidden")){e.preventDefault();isPauseOpen()?closePauseMenu():openPauseMenu();return}
    if(isPauseOpen())return;
    if(e.code==="Enter"&&!$("hud").classList.contains("hidden")){e.preventDefault();openChat();return}
    if((e.code==="AltLeft"||e.code==="AltRight")&&!$("hud").classList.contains("hidden")&&local.alive&&!e.repeat){e.preventDefault();triggerAltParry();return}
    keys[e.code]=true;
    if(handleSpectatorKey(e))return;
    if(e.code==="KeyQ"&&!$("hud").classList.contains("hidden")){e.preventDefault();castDragonQ()}
    if(/^Digit[1-4]$/.test(e.code)&&local.alive)setSelectedCard(parseInt(e.code.at(-1))-1)
  });
  addEventListener("keyup",e=>{if(e.target?.id==="chatInput")return;keys[e.code]=false});
  addEventListener("wheel",e=>{if($("hud").classList.contains("hidden")||isPauseOpen()||!local.alive||e.target?.closest?.(".chat"))return;e.preventDefault();setSelectedCard(selectedCard+(e.deltaY>0?1:-1))},{passive:false});
  addEventListener("mousemove",e=>{if(isPauseOpen()||document.pointerLockElement!==document.body)return;local.rot.y-=e.movementX*.0022;local.rot.x=clamp(local.rot.x-e.movementY*.0022,-1.35,1.35)});
  addEventListener("mousedown",e=>{
    if(e.target?.closest?.(".chat")||isPauseOpen())return;
    if($("hud").classList.contains("hidden"))return;
    const cardNode=e.target?.closest?.(".card");
    if(cardNode&&local.alive)setSelectedCard(parseInt(cardNode.dataset.card)||0);
    if(cardNode&&e.button!==2)return;
    if(document.pointerLockElement!==document.body)lockPointer();
    if(!local.alive)return;
    if(e.button===0)castCard();
    if(e.button===2)startChargeSkill()
  });
  addEventListener("mouseup",e=>{if(e.button===2)releaseChargeSkill()});
  addEventListener("contextmenu",e=>e.preventDefault())
}
function isUltimateCard(card,index){return index===3||card?.ultimate||card?.type==="궁극기"}
function cardInfo(card){const parts=[card.damage?"피해 "+Math.round(card.damage*local.power):"보조"];if(card.curse)parts.push("저주 "+Math.round(card.curse*local.power));if(card.heal)parts.push("회복 "+Math.round(card.heal*local.power));if(card.shield)parts.push("방어 "+Math.round(card.shield*local.power));if(card.healCut)parts.push("회복감소 "+Math.round((1-Math.max(card.healCut,.4))*100)+"%");return parts.join(" · ")}
function rightHoldInfo(card,i){if(i!==0&&i!==3)return"우클릭 없음";if(local.element==="fire"&&i===0)return"우클릭 화염차징";if(local.element==="fire"&&i===3)return"우클릭 태양차징";if(local.element==="water"&&i===0)return"우클릭 물광선";if(local.element==="psychic"&&i===3)return"우클릭 염동차징";if(local.element==="dragon"&&i===0)return"우클릭 화염빔";if(i===0&&card.type==="공격")return"우클릭 지속공격";if(i===3)return"우클릭 차징";return"우클릭 없음"}
function cardStatValue(card,key){if(key==="damage")return Math.max(0,Math.round(((card.damage||0)+(card.burn||0)+(card.poison||0)+(card.curse||0))*local.power));if(key==="mana")return Math.max(0,Math.round(card.mana||0));return Math.max(.1,Math.round(Math.max(.2,(card.cd||1)*local.cdMul)*10)/10)}
function cardStatPct(card,key){const v=cardStatValue(card,key);if(key==="damage")return clamp(v/95*100,8,100);if(key==="mana")return clamp(v/110*100,8,100);return clamp(v/65*100,8,100)}
function cardSuit(id){return id==="fire"?"🔥":id==="water"?"💧":id==="lightning"?"⚡":id==="earth"?"⛰":id==="wind"?"🌀":id==="light"?"✦":id==="darkness"?"☾":id==="poison"?"☣":id==="dragon"?"🐉":id==="psychic"?"◇":id==="summoner"?"✥":id==="hacker"?"⌘":"✹"}
