function skillProjectileSpeed(id,card){if(window.BFCore?.speed)return window.BFCore.speed(id,card);if(card?.psychicLift)return 6;if(card?.wave)return 3.8;if(card?.shield||card?.heal||card?.gravity||card?.roundSeal)return 0;if(card?.sun)return clamp(5-(card.charge||0)*2,3,5);if(card?.stream)return id==="lightning"||id==="light"||id==="dragon"?10:id==="wind"||id==="hacker"?9:id==="water"||id==="poison"||id==="psychic"?8:id==="earth"?6:7;if(isUltimateCard(card))return id==="dragon"?0:id==="fire"?4:id==="water"?5:id==="lightning"?10:id==="earth"?5:id==="wind"?1:id==="light"?10:id==="darkness"?4:id==="poison"||id==="summoner"?2:id==="hacker"?0:4;if(crowdControlCard(card))return id==="dragon"?0:id==="fire"?0:id==="water"?6:id==="lightning"?10:id==="earth"?5:id==="wind"?6:id==="light"?9:id==="darkness"?7:id==="poison"?5:id==="psychic"?9:id==="hacker"?8:6;return id==="lightning"||id==="light"?10:id==="hacker"||id==="wind"?9:id==="water"||id==="poison"||id==="psychic"?8:id==="fire"||id==="darkness"||id==="dragon"||id==="summoner"?7:id==="earth"?6:7}
