function useCastMotion(card){if(!viewModel)return;const ultimate=isUltimateCard(card);viewModel.userData.kick=ultimate ? .32 : .18;viewModel.userData.pulse=ultimate ? .4 : .22}
function updateEffects(dt){for(let i=effects.length-1;i>=0;i--){const e=effects[i];if(!e.max)e.max=e.life||.1;e.life-=dt;if(e.mesh.userData.v)e.mesh.position.addScaledVector(e.mesh.userData.v,dt);e.mesh.scale.multiplyScalar(1+dt*(e.mesh.userData.grow??3));if(e.mesh.material)e.mesh.material.opacity=Math.max(0,e.life/e.max);if(e.life<=0){scene.remove(e.mesh);effects.splice(i,1)}}}
function spawn(pos,color,count){if(!scene)return;for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.08,6,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));m.position.set(pos.x+(Math.random()-.5)*1.5,pos.y-1+Math.random()*1.5,pos.z+(Math.random()-.5)*1.5);m.userData.v=new THREE.Vector3((Math.random()-.5)*5,Math.random()*3,(Math.random()-.5)*5);const life=.5+Math.random()*.4;scene.add(m);effects.push({mesh:m,life,max:life})}}
function upgradeLabel(k){const map={mana:"마나증가",power:"능력증폭",hp:"체력증가",cool:"쿨감",evolve:"진화",crown:"왕관",other:"랜덤능력",devil:"악마화",oluo:"올루오",rest:"휴식",dragon_fang:"드래곤 이빨",dragon_wing:"드래곤 날개",dragon_tail:"드래곤 꼬리",dragon_body:"드래곤 몸",dragon_eye:"드래곤 눈",hacker_discount:"해커 오버클럭",hacker_backdoor:"백도어 강화",psy_mastery:"무중력 숙련",spirit_blessing:"대정령 축복"};if(String(k).startsWith("dedicated"))return`전용 ${Number(String(k).replace("dedicated",""))+1}번`;return map[k]||k}
function upgradeSummary(p){const counts={...(p.upgradeCounts||{})};if(p.devil&&!counts.devil)counts.devil=1;if(p.oluo&&!counts.oluo)counts.oluo=1;const text=Object.entries(counts).filter(([,v])=>v>0).map(([k,v])=>`${upgradeLabel(k)} - ${v}`).join(" · ");return text||"구매 없음"}
function updateHud(r){const roundLabel=r.battleFinishAt?`상점까지 ${Math.max(0,Math.ceil((r.battleFinishAt-now())/1000))}초`:`ROUND ${r.round} / ${r.maxRounds}`;$("hpText").textContent=Math.round(local.hp)+(local.shield?" +"+Math.round(local.shield):"");$("manaText").textContent=Math.round(local.mana);$("roundText").textContent=`${r.round} / ${r.maxRounds}`;$("roundCenter").textContent=roundLabel;$("hpBar").style.width=clamp(local.hp/local.maxHp*100,0,100)+"%";$("manaBar").style.width=clamp(local.mana/local.maxMana*100,0,100)+"%";$("roundBar").style.width=clamp(r.round/r.maxRounds*100,0,100)+"%";$("scoreboard").innerHTML=`<div class="score-title"><span>구매 현황</span><b>${Object.keys(r.players).length}명</b></div>`+Object.values(r.players).sort(scoreSort).map(p=>`<div class="score-line"><span>${esc(p.name)}${p.id===selfId?" · 나":""}</span><b>${esc(upgradeSummary(p))}</b></div>`).join("");renderChat(r)}
function scoreSort(a,b){return (b.wins||0)-(a.wins||0)||(b.kills||0)-(a.kills||0)||(b.damageDone||0)-(a.damageDone||0)||(a.deaths||0)-(b.deaths||0)}
function finalRanking(r){return Object.values(r?.players||{}).map(p=>({...p,wins:Number(p.wins)||0,kills:Number(p.kills)||0,deaths:Number(p.deaths)||0,damageDone:Number(p.damageDone)||0})).sort(scoreSort).slice(0,4)}
function showEnd(){showOnly("endScreen");const r=getRoom();if(!r)return;const rows=(r.finalStats?.length?r.finalStats:finalRanking(r));$("endTitle").textContent="StellaCard 최종 결과";$("finalScores").innerHTML=rows.map((p,i)=>{const rank=p.finalRank||i+1,elementName=elements[p.element]?.name||"미선택";return`<div class="final-row rank-${rank}"><span><strong>${rank}위</strong>${esc(p.name)}${p.team?" · 팀 "+p.team:""} · ${elementName} · ${finalStatusLabel(p)}</span><b>승리 ${p.wins||0}승 · 처치 ${p.kills||0} · 피해 ${Math.round(p.damageDone||0)} · 사망 ${p.deaths||0}</b></div>`}).join("");tickEnd()}
function tickEnd(){const r=getRoom();if(!r)return;const ids=Object.keys(r.players),ready=r.endReady||{},count=ids.filter(id=>ready[id]).length,left=r.returnLobbyAt?Math.max(0,Math.ceil((r.returnLobbyAt-now())/1000)):0,meReady=!!ready[selfId];$("endContinue").disabled=meReady;$("endContinue").textContent=meReady?"대기 중":"넘어가기";$("endStatus").textContent=r.returnLobbyAt?`${count}/${ids.length}명 선택 · ${left}초 뒤 대기실로 이동`:`${count}/${ids.length}명 선택 · 모두 누르면 바로 이동`;}
function endContinue(){const r=getRoom();if(!r||r.phase!=="end")return;r.endReady={...(r.endReady||{}),[selfId]:true};if(!r.returnLobbyAt)r.returnLobbyAt=now()+10000;if(Object.keys(r.players).every(id=>r.endReady[id]))resetToLobby(r);else saveRoom(r);tickEnd()}





function showUpgrade(){showOnly("upgradeScreen");upgradePicked=false;message("upgradeStatus","");const r=getRoom(),p=r?.players?.[selfId];if(!r||!p)return;syncLocalProgress(p);upgradePicked=!!p.upgradeReady;$("upgradeTitle").textContent=`${r.round}라운드 종료 강화 선택`;$("upgradeDesc").textContent=`상점은 라운드에 포함되지 않습니다. 한 명 이상 선택하면 5초 뒤 ${r.pendingRound||r.round+1}라운드가 시작됩니다.`;buildUpgradeOptions(p,r);tickUpgrade()}
function rng(seed){let x=Math.sin(seed)*10000;return x-Math.floor(x)}
function sample(arr,n,seed){const a=[...arr],out=[];for(let i=0;i<n&&a.length;i++){const k=Math.floor(rng(seed+i*91)*a.length);out.push(a.splice(k,1)[0])}return out}
function dedicatedCard(p,seed){const e=elements[p.element]||elements.fire,rare=rng(seed)>0.72,idx=Math.floor(rng(seed+7)*e.cards.length),base=e.cards[idx];return{kind:"dedicated"+idx,title:rare?`희귀 전용 ${base.name}`:`전용 ${base.name}`,desc:`${base.name} 피해와 효과가 증가합니다. 전용 강화는 원소 개성을 강화합니다.`,apply:q=>{q.power+=rare?0.12:0.08}}}
function activateDevil(q){if(q.devil)return;q.devil=true;q.power=(q.power||1)+.12;q.drain=Math.max(q.drain||0,.1);q.maxHp=Math.min(220,(q.maxHp||100)+20);q.maxMana=Math.max(q.maxMana||100,110);q.hp=q.maxHp}
function activateOluo(q){if(!q.devil)activateDevil(q);if(q.oluo)return;q.oluo=true;q.power=(q.power||1)+.18;q.drain=Math.max(q.drain||0,.16);q.maxHp=Math.min(220,(q.maxHp||100)+35);q.maxMana=Math.max(q.maxMana||100,125);q.hp=q.maxHp}
function updateAscension(q){if((q.evolve||0)>=5)q.maxMana=Math.max(q.maxMana||100,110);if((q.crowns||0)>=7)q.maxMana=Math.max(q.maxMana||100,110)}
function dragonPartComplete(q){const parts=q.dragonParts||{};if(["fang","wing","tail","body","eye"].every(k=>parts[k])&&!q.dragonComplete){q.dragonComplete=true;q.maxHp=Math.max(q.maxHp||100,1200);q.hp=q.maxHp;q.power=Math.min(2.2,(q.power||1)+.25);q.maxMana=Math.max(q.maxMana||100,160)}}
