function specialUpgradeCards(p){const cards=[];if(hasElement(p,"hacker")&&upgradeCount(p,"hacker_discount")<1)cards.push({kind:"hacker_discount",title:"해커 오버클럭",desc:"해커 전용 최적화로 최대 마나가 증가합니다.",apply:q=>{q.maxMana=Math.max(q.maxMana||100,120)}});if(hasElement(p,"hacker")&&upgradeCount(p,"hacker_backdoor")<1)cards.push({kind:"hacker_backdoor",title:"백도어 강화",desc:"랜덤 추가 강화 확률이 10%에서 13%로 증가합니다.",apply:q=>{q.power=(q.power||1)+.04}});if(hasElement(p,"psychic")&&upgradeCount(p,"psy_mastery")<1)cards.push({kind:"psy_mastery",title:"무중력 숙련",desc:"염동력 범위와 밀쳐내기 성능이 증가합니다.",apply:q=>{q.power=(q.power||1)+.08;q.maxMana=Math.max(q.maxMana||100,125)}});if(hasElement(p,"summoner")&&upgradeCount(p,"spirit_blessing")<1)cards.push({kind:"spirit_blessing",title:"대정령의 축복",desc:"정령술사 회복과 보호 효과가 증가합니다.",apply:q=>{q.power=(q.power||1)+.06;q.maxMana=Math.max(q.maxMana||100,130)}});if((p.crowns||0)>=7&&!p.devil)cards.push({kind:"devil",title:"악마화 카드",desc:"왕관 7회 후 개방. 악마 카드, 흡혈, 저주 피해를 얻지만 마나 소모가 증가합니다.",apply:activateDevil});if((p.evolve||0)>=5&&(p.crowns||0)>=7&&p.devil&&!p.oluo)cards.unshift({kind:"oluo",title:"올루오푸스 강림",desc:"최종 진화와 악마화를 합친 최종 상태. 전용 카드 4종으로 변경됩니다.",apply:activateOluo});return cards}
function canOfferUpgrade(p,o){
  if(o.kind==="mana")return upgradeCount(p,o.kind)<5;
  if(o.kind==="power"||o.kind==="hp"||o.kind==="cool")return upgradeCount(p,o.kind)<5;
  if(o.kind==="evolve")return (p.evolve||0)<5;
  if(o.kind==="crown")return (p.crowns||0)<7;
  if(o.kind==="other")return (p.secondaryElements||[]).length<3;
  if(o.kind==="devil")return (p.crowns||0)>=7&&!p.devil;
  if(o.kind==="oluo")return (p.evolve||0)>=5&&(p.crowns||0)>=7&&p.devil&&!p.oluo;
  if(String(o.kind).startsWith("dragon_"))return hasElement(p,"dragon")&&!p.dragonParts?.[String(o.kind).replace("dragon_","")];
  if(String(o.kind).startsWith("dedicated"))return upgradeCount(p,o.kind)<2;
  return true;
}
function upgradeSnapshot(p){return{maxHp:p.maxHp??100,hp:p.hp??p.maxHp??100,shield:p.shield||0,maxMana:p.maxMana??100,mana:p.mana??p.maxMana??100,power:p.power||1,move:p.move||1,moveBase:p.moveBase||1,cdMul:p.cdMul||1,evolve:p.evolve||0,crowns:p.crowns||0,drain:p.drain||0,devil:!!p.devil,oluo:!!p.oluo,dragonParts:{...(p.dragonParts||{})},dragonComplete:!!p.dragonComplete,dragonWing:!!p.dragonWing,dragonTail:!!p.dragonTail,dragonBody:!!p.dragonBody,dragonEye:!!p.dragonEye,shieldBoost:p.shieldBoost||0,spirit:p.spirit||"fire",secondaryElements:[...(p.secondaryElements||[])],upgradeCounts:{...(p.upgradeCounts||{})}}}
function restoreUpgradeSnapshot(p,s){if(!s)return p;Object.assign(p,{maxHp:s.maxHp,hp:s.hp,shield:s.shield||0,maxMana:s.maxMana,mana:s.mana,power:s.power,move:s.move,moveBase:s.moveBase,cdMul:s.cdMul,evolve:s.evolve,crowns:s.crowns,drain:s.drain,devil:!!s.devil,oluo:!!s.oluo,dragonParts:{...(s.dragonParts||{})},dragonComplete:!!s.dragonComplete,spirit:s.spirit||"fire",secondaryElements:[...(s.secondaryElements||[])],upgradeCounts:{...(s.upgradeCounts||{})},shieldBoost:s.shieldBoost||0});["dragonWing","dragonTail","dragonBody","dragonEye"].forEach(k=>{if(s[k])p[k]=true;else delete p[k]});return p}
function ensureUpgradeBase(p){if(!p.upgradeBase)p.upgradeBase=upgradeSnapshot(p);return p.upgradeBase}
function upgradeOfferPlayer(p){if(!p.upgradeBase)return p;const q={...p,dragonParts:{...(p.dragonParts||{})},secondaryElements:[...(p.secondaryElements||[])],upgradeCounts:{...(p.upgradeCounts||{})}};return restoreUpgradeSnapshot(q,p.upgradeBase)}
function syncLocalUpgradeProgress(p){local.maxHp=p.maxHp;local.maxMana=p.maxMana;local.power=p.power;local.move=p.move;local.moveBase=p.moveBase||1;local.cdMul=p.cdMul;local.evolve=p.evolve;local.crowns=p.crowns;local.drain=p.drain||0;local.devil=p.devil;local.oluo=p.oluo;local.dragonParts={...(p.dragonParts||{})};local.dragonComplete=!!p.dragonComplete;local.spirit=p.spirit||"fire";local.upgradeCounts={...(p.upgradeCounts||{})};local.secondaryElements=[...(p.secondaryElements||[])]}
function commonUpgradePool(){return[
{kind:"mana",title:"마나증가",desc:"최대 마나 50 증가. 최대 5중첩",apply:q=>{q.maxMana=Math.min(350,(q.maxMana||100)+50);q.mana=clamp((q.mana||0)+50,0,q.maxMana)}},
{kind:"power",title:"능력증폭",desc:"카드 피해와 회복 6% 증가. 최대 5중첩",apply:q=>{q.power+=.06}},
{kind:"hp",title:"체력증가",desc:"최대 체력 12 증가, 즉시 12 회복",apply:q=>{q.maxHp=Math.min(200,(q.maxHp||100)+12);q.hp=clamp((q.hp||0)+12,0,q.maxHp)}},
{kind:"cool",title:"쿨타임감소",desc:"전체 카드 쿨타임 5% 감소",apply:q=>{q.cdMul=Math.max(.75,(q.cdMul||1)*.95)}},
{kind:"evolve",title:"진화",desc:"5번 강화하면 최종 진화. 대쉬와 MP 회복도 강화",apply:q=>{q.evolve=Math.min(5,(q.evolve||0)+1);if(q.evolve>=5){q.power+=.2;q.maxHp=Math.min(220,(q.maxHp||100)+20);q.hp=q.maxHp}updateAscension(q)}},
{kind:"crown",title:"왕관",desc:"7번 구매하면 악마화 조건 완료",apply:q=>{q.crowns=Math.min(7,(q.crowns||0)+1);q.power+=.08;if(q.crowns>=2)q.drain=(q.drain||0)+.05;updateAscension(q)}},
{kind:"other",title:"랜덤 다른 능력카드",desc:"다른 원소를 보조 능력으로 흡수하고 주변 장식으로 표시",apply:q=>{const pool=elementKeys.filter(x=>x!==q.element&&!(q.secondaryElements||[]).includes(x));const pick=pool[Math.floor(Math.random()*pool.length)]||elementKeys[0];q.secondaryElements=[...(q.secondaryElements||[]),pick].slice(-3);q.power+=.05;q.maxMana=Math.min(350,(q.maxMana||100)+8)}}
]}
function buildUpgradeOptions(p,r){const offer=upgradeOfferPlayer(p),common=commonUpgradePool();
let pool=common.filter(o=>canOfferUpgrade(offer,o));const seed=r.upgradeSeed+parseInt(selfId.replace(/\D/g,"").slice(0,5)||"7"),specials=specialUpgradeCards(offer).filter(o=>canOfferUpgrade(offer,o));let options=specials.slice(0,1);options.push(...sample(pool,3-options.length,seed));const dedicated=dedicatedCard(offer,r.upgradeSeed+23);if(canOfferUpgrade(offer,dedicated)&&rng(r.upgradeSeed+99)>.58){const replaceAt=options.findIndex(o=>!specials.includes(o));if(replaceAt>=0)options[replaceAt]=dedicated;else if(options.length<3)options.push(dedicated)}const dragonPool=dragonPartCards(offer).filter(o=>canOfferUpgrade(offer,o));if(r.round>=4&&dragonPool.length&&rng(r.upgradeSeed+501)<.05){const pick=dragonPool[Math.floor(rng(r.upgradeSeed+777)*dragonPool.length)],replaceAt=Math.max(0,options.findIndex(o=>!specials.includes(o)));options[replaceAt]=pick}if(!options.length)options=[{kind:"rest",title:"휴식",desc:"더 이상 선택 가능한 강화가 없습니다. 체력과 마나를 회복합니다.",apply:q=>{q.hp=q.maxHp;q.mana=q.maxMana}}];const box=$("upgradeOptions"),draft=p.upgradeDraft?.kind||"";box.innerHTML="";options.slice(0,3).forEach(o=>{const d=document.createElement("div");d.className="upgrade-card"+(draft===o.kind?" selected":"");d.innerHTML=`<h3>${o.title}</h3><p>${o.desc}</p><span class="tag">무료 선택</span>`;d.onclick=()=>pickUpgrade(o,d);box.appendChild(d)})}
function syncLocalProgress(p){if(p.gameId&&local.gameId&&p.gameId!==local.gameId)local.gameId=p.gameId;return p}
function hackerBackdoor(p){if(!hasElement(p,"hacker"))return"";const chance=upgradeCount(p,"hacker_backdoor")>0?.13:.1;if(Math.random()>=chance)return"";const pool=commonUpgradePool().filter(o=>o.kind!=="oluo"&&canOfferUpgrade(p,o));if(!pool.length)return"";const pick=pool[Math.floor(Math.random()*pool.length)];pick.apply(p);markUpgrade(p,pick.kind);return` · 백도어 추가 강화: ${pick.title}`}
function tickUpgrade(){const r=getRoom();if(!r)return;const players=Object.values(r.players||{}),ready=players.filter(p=>p.upgradeReady).length,total=players.length,left=r.nextStartAt?Math.max(0,Math.ceil((r.nextStartAt-now())/1000)):0,p=r.players?.[selfId],picked=p?.upgradeDraft?.title||"";$("upgradeTimer").textContent=r.nextStartAt?`${left}초`:"선택 대기";message("upgradeStatus",picked?`${picked} 선택됨 · 시작 전까지 변경 가능 · ${ready}/${total} 선택 · ${left}초 뒤 자동 시작`:ready?`${ready}/${total} 선택 · ${left}초 뒤 자동 시작`:"한 명 이상 선택하면 5초 뒤 자동 시작됩니다.")}
function pickUpgrade(o,node){const r=getRoom(),p=r?.players?.[selfId];if(!p){message("upgradeStatus","플레이어 정보를 다시 불러오지 못했습니다.");return}syncLocalProgress(p);const base=ensureUpgradeBase(p);restoreUpgradeSnapshot(p,base);if(!canOfferUpgrade(p,o)&&o.kind!=="rest"){message("upgradeStatus","이미 최대 강화에 도달했습니다.");buildUpgradeOptions(p,r);return}o.apply(p);markUpgrade(p,o.kind);const backdoor=hackerBackdoor(p);p.upgradeReady=true;p.upgradeDraft={kind:o.kind,title:o.title,chosenAt:now(),backdoor};syncLocalUpgradeProgress(p);r.players[selfId]=p;if(Object.values(r.players).some(x=>x.upgradeReady)&&!r.nextStartAt)r.nextStartAt=now()+5000;saveRoom(r);upgradePicked=true;document.querySelectorAll(".upgrade-card").forEach(x=>x.classList.remove("selected"));node.classList.add("selected");tickUpgrade()}



